<?php require_once __DIR__.'/../../app/bootstrap.php';guard();$p=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['id'];$amount=(int)$_POST['amount'];if($amount>0)credit_wallet($p,$id,$amount,'شارژ دستی مدیر',0);}$q=trim($_GET['q']??'');if($q){$st=$p->prepare("SELECT * FROM users WHERE CAST(telegram_id AS CHAR) LIKE ? OR username LIKE ? OR first_name LIKE ? ORDER BY id DESC LIMIT 100");$x="%$q%";$st->execute([$x,$x,$x]);$rows=$st->fetchAll();}else$rows=$p->query("SELECT * FROM users ORDER BY id DESC LIMIT 100")->fetchAll();?><!doctype html><html lang=fa dir=rtl><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>کاربران</title><style>body{font-family:Tahoma;background:#f4f8fc}.wrap{max-width:1100px;margin:30px auto}.card{background:#fff;padding:20px;border-radius:18px}input{padding:9px}button{background:#1687d9;color:#fff;border:0;padding:9px;border-radius:8px}table{width:100%;border-collapse:collapse}td,th{padding:9px;border-bottom:1px solid #eee}</style><div class=wrap><a href=/admin/index.php>← داشبورد</a><div class=card><h2>👥 کاربران</h2><form><input name=q value="<?=e($q)?>" placeholder="جستجو"><button>جستجو</button></form><table><tr><th>ID</th><th>نام</th><th>Username</th><th>موجودی</th><th>شارژ دستی</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['telegram_id'])?></td><td><?=e(trim(($r['first_name']??'').' '.($r['last_name']??'')))?></td><td><?=e($r['username']??'')?></td><td><?=money((int)$r['wallet_balance'])?></td><td><form method=post><input type=hidden name=csrf value="<?=e(csrf())?>"><input type=hidden name=id value=<?=$r['id']?>><input type=number name=amount min=1 placeholder="تومان"><button>شارژ</button></form></td></tr><?php endforeach;?></table></div></div>
